def reward_structured_enumeration(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(-1.0)
            continue

        # Count enumeration steps (e.g., "For n = 1:", "Case 1:", "- ")
        enum_markers = re.findall(r'(For\s+[a-zA-Z_0-9]+\s*=|Case\s+\d+:|\d+\.\s*\*\*|\-\s*\[)', thinking)
        enum_count = len(enum_markers)

        # Check for systematic progression (numbers increasing)
        numbers = re.findall(r'\b(\d+)\b', thinking)
        progress_count = 0
        for i in range(len(numbers) - 1):
            try:
                if int(numbers[i+1]) > int(numbers[i]):
                    progress_count += 1
            except ValueError:
                pass

        score = 0.0
        if enum_count > 3:
            score += 1.5
        if progress_count > 5:
            score += 1.0

        # Penalize if thinking is very long but no clear enumeration structure
        if len(thinking) > 2000 and enum_count < 2:
            score -= 1.0

        scores.append(score)
    return scores

def penalize_negative_combinatorics(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        sol_match = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if not sol_match:
            scores.append(0.0)
            continue

        pred_str = sol_match.group(1).strip()
        # Extract numbers from prediction
        nums = re.findall(r'-?\d+\.?\d*', pred_str)
        has_negative = False
        for num in nums:
            try:
                val = float(num)
                if val < 0:
                    has_negative = True
                    break
            except ValueError:
                pass

        if has_negative:
            # Combinatorics problems rarely have negative answers
            scores.append(-2.0)
        else:
            scores.append(0.0)
    return scores

def reward_integer_final_for_integer_gt(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        sol_match = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if not sol_match:
            scores.append(-1.0)
            continue

        pred_str = sol_match.group(1).strip()
        # Check if ground truth is an integer
        gt_nums = re.findall(r'-?\d+', true_answer)
        gt_is_integer = bool(gt_nums) and all('.' not in n for n in gt_nums)

        # Check if prediction is an integer
        pred_nums = re.findall(r'-?\d+\.?\d*', pred_str)
        pred_is_integer = True
        if pred_nums:
            for n in pred_nums:
                if '.' in n:
                    # Check if it's a whole number like 5.0
                    if not n.endswith('.0'):
                        pred_is_integer = False
                        break
        else:
            pred_is_integer = False

        score = 0.0
        if gt_is_integer:
            if pred_is_integer:
                score += 1.0
            else:
                score -= 1.5
        scores.append(score)
    return scores

def penalize_inconsistent_intermediate_results(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        if not thinking:
            scores.append(0.0)
            continue

        # Extract all numbers from thinking
        numbers = re.findall(r'\b\d+\b', thinking)

        # Check for sudden large jumps in magnitude that might indicate error
        # Simple heuristic: if a number is much larger than the previous one and the context suggests counting
        inconsistency_score = 0.0
        for i in range(1, len(numbers)):
            try:
                prev = int(numbers[i-1])
                curr = int(numbers[i])
                if prev > 0 and curr > prev * 10 and curr < 1000000:
                    inconsistency_score += 0.2
            except ValueError:
                pass

        if inconsistency_score > 1.0:
            scores.append(-1.0)
        else:
            scores.append(0.0)
    return scores

